-- Database source of truth for static county profiles and public/MCP data access.
-- Created with `supabase migration new county_statistics`, ordered after existing history.
create table public.county_geographies (
  fips text primary key check (fips ~ '^13[0-9]{3}$'),
  name text not null check (length(btrim(name)) between 1 and 100),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  kind text not null check (kind in ('county','state')),
  check ((kind='state') = (fips='13000'))
);
create table public.county_statistic_topics (
  id text primary key, title text not null, note text not null default '', position integer not null check(position>=0)
);
create table public.county_statistic_indicators (
  code text primary key check (length(code) between 1 and 80),
  topic_id text not null references public.county_statistic_topics(id),
  label text not null check(length(btrim(label)) between 1 and 200),
  unit text not null check(unit in ('count','percent','usd','square_miles','minutes','ratio','density')),
  definition text not null default '', position integer not null check(position>=0),
  headline_position integer unique check(headline_position between 0 and 5)
);
create table public.county_statistic_sources (
  id text primary key, publisher text not null, title text not null,
  source_url text not null check (source_url ~ '^https://[^[:space:]]+$'),
  retrieved_on date not null,
  sha256 text not null check(sha256 ~ '^[0-9a-f]{64}$')
);
create table public.county_statistics (
  county_fips text not null references public.county_geographies(fips),
  indicator_code text not null references public.county_statistic_indicators(code),
  value numeric, status text not null default 'available' check(status in ('available','suppressed','unavailable')),
  period text not null check(length(btrim(period)) between 1 and 200),
  source_id text not null references public.county_statistic_sources(id),
  source_variables text not null check(length(btrim(source_variables)) between 1 and 2000),
  numerator numeric, denominator numeric check(denominator>0),
  margin_of_error numeric check(margin_of_error>=0),
  lower_bound numeric, upper_bound numeric, confidence_level numeric check(confidence_level>0 and confidence_level<100),
  detail text not null default '', components jsonb not null default '{}'::jsonb check(jsonb_typeof(components)='object'),
  updated_at timestamptz not null default now(),
  primary key(county_fips,indicator_code),
  check ((status='available') = (value is not null)),
  check(value is null or value not in ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)),
  check(numerator is null or numerator not in ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)),
  check(denominator is null or denominator not in ('NaN'::numeric,'Infinity'::numeric)),
  check(margin_of_error is null or margin_of_error not in ('NaN'::numeric,'Infinity'::numeric)),
  check((lower_bound is null)=(upper_bound is null)),
  check(lower_bound is null or (lower_bound<=value and value<=upper_bound)),
  check(lower_bound is null or confidence_level is not null)
);
create index county_statistics_indicator on public.county_statistics(indicator_code,county_fips);

create function public.validate_county_statistic() returns trigger language plpgsql set search_path='' as $$
declare unit_name text;
begin
  select unit into unit_name from public.county_statistic_indicators where code=new.indicator_code;
  if new.value is not null and ((unit_name='percent' and (new.value>100 or new.value<case when new.indicator_code='PST120225' then -100 else 0 end))
    or (unit_name<>'percent' and new.value<0)) then raise exception 'Statistic value outside its unit range' using errcode='23514'; end if;
  new.updated_at=clock_timestamp();
  return new;
end;
$$;
revoke all on function public.validate_county_statistic() from public,anon,authenticated;
create trigger county_statistic_validate before insert or update on public.county_statistics for each row execute function public.validate_county_statistic();

do $$ declare resource text; begin
 foreach resource in array array['county_geographies','county_statistic_topics','county_statistic_indicators','county_statistic_sources','county_statistics'] loop
  execute format('alter table public.%I enable row level security',resource);
  execute format('revoke all on public.%I from public,anon,authenticated',resource);
  execute format('grant select on public.%I to anon,authenticated',resource);
  execute format('grant insert,update,delete on public.%I to authenticated',resource);
  execute format('create policy public_read on public.%I for select to anon,authenticated using (true)',resource);
  execute format('create policy admin_insert on public.%I for insert to authenticated with check ((select public.is_admin()))',resource);
  execute format('create policy admin_update on public.%I for update to authenticated using ((select public.is_admin())) with check ((select public.is_admin()))',resource);
  execute format('create policy admin_delete on public.%I for delete to authenticated using ((select public.is_admin()))',resource);
  execute format('create trigger frontend_rebuild_required after insert or update or delete or truncate on public.%I for each statement execute function frontend_private.mark_frontend_rebuild_required()',resource);
 end loop;
end $$;

create view public.county_statistic_records with (security_invoker=true) as
select v.*,g.name as county_name,g.slug as county_slug,g.kind as geography_kind,
 i.label,i.unit,i.definition,i.position as indicator_position,i.headline_position,
 t.id as topic_id,t.title as topic_title,t.note as topic_note,t.position as topic_position,
 s.publisher,s.title as source_title,s.source_url,s.retrieved_on,s.sha256
from public.county_statistics v join public.county_geographies g on g.fips=v.county_fips
 join public.county_statistic_indicators i on i.code=v.indicator_code
 join public.county_statistic_topics t on t.id=i.topic_id
 join public.county_statistic_sources s on s.id=v.source_id;
revoke all on public.county_statistic_records from public,anon,authenticated;
grant select on public.county_statistic_records to anon,authenticated;

create function public.search_county_statistics(p_query text default '',p_county_fips text default null,
 p_indicator_code text default null,p_topic text default null,p_limit integer default 100,p_offset integer default 0)
returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare result jsonb; page_limit integer:=least(greatest(coalesce(p_limit,100),1),500); page_offset integer:=greatest(coalesce(p_offset,0),0);
begin
 if length(coalesce(p_query,''))>500 then raise exception 'Query too long' using errcode='22023'; end if;
 with matched as materialized (
  select r.* from public.county_statistic_records r
  where (p_county_fips is null or r.county_fips=p_county_fips)
   and (p_indicator_code is null or r.indicator_code=p_indicator_code)
   and (p_topic is null or r.topic_id=p_topic)
   and (btrim(coalesce(p_query,''))='' or pg_catalog.to_tsvector('english',r.county_name||' '||r.county_fips||' '||r.label||' '||r.definition||' '||r.topic_title||' '||r.publisher||' '||r.source_title||' '||r.period||' '||r.indicator_code||' '||coalesce(r.value::text,'')) @@ pg_catalog.websearch_to_tsquery('english',p_query))
 ), page as (select * from matched order by county_fips,topic_position,indicator_position,indicator_code limit page_limit offset page_offset)
 select jsonb_build_object('results',coalesce((select jsonb_agg(to_jsonb(page) order by county_fips,topic_position,indicator_position,indicator_code) from page),'[]'::jsonb),
 'total_count',(select count(*) from matched),'limit',page_limit,'offset',page_offset) into result;
 return result;
end;
$$;
revoke all on function public.search_county_statistics(text,text,text,text,integer,integer) from public,anon,authenticated;
grant execute on function public.search_county_statistics(text,text,text,text,integer,integer) to anon,authenticated;

